const S={screen:'announce',players:[{id:1,name:'Лена',reply:'Иду',arrival:'pending',paid:false,note:'Привести подругу'}, {id:2,name:'Саша',reply:'Пока думаю',arrival:'pending',paid:false,note:''},{id:3,name:'Миша',reply:'Иду',arrival:'pending',paid:false,note:'Опытный игрок'},{id:4,name:'Даша',reply:'Приду позже',arrival:'pending',paid:false,note:''},{id:5,name:'Игорь',reply:'Не иду',arrival:'pending',paid:false,note:''}],games:[],modal:null};
const $=s=>document.querySelector(s); const yes=p=>['Иду','Приду позже'].includes(p.reply); const arrived=p=>p.arrival==='here';
function go(screen){S.screen=screen;S.modal=null;render()} function open(m){S.modal=m;render()} function close(){S.modal=null;render()}
function header(){return `<div class="top"><h1>Вечер · 14 августа</h1><div class="sub">Суп с Котом · 20:00 · клубная игра</div><div class="tabs"><button class="${S.screen==='announce'?'active':''}" onclick="go('announce')">Анонс</button><button class="${S.screen==='replies'?'active':''}" onclick="go('replies')">Ответы</button><button class="${S.screen==='live'?'active':''}" onclick="go('live')">На месте</button><button class="${S.screen==='games'?'active':''}" onclick="go('games')">Игры</button></div></div>`}
function announce(){let n=S.players.filter(p=>p.reply==='').length;return `<section class="card hero"><h2>Анонс вечера</h2><p class="sub">Сначала публикуешь дату, затем видишь доставку и ответы. Никаких настроек состава здесь нет.</p><button class="primary" onclick="open('send')">${n?'Отправить приглашения':'Приглашения уже отправлены'}</button></section><section class="card"><h3>После рассылки</h3><div class="grid"><div class="stat"><b>${S.players.filter(yes).length}</b><span class="tiny">идут / позже</span></div><div class="stat"><b>${S.players.filter(p=>p.reply==='Пока думаю').length}</b><span class="tiny">ждём ответа</span></div></div><button class="outline" style="width:100%;margin-top:10px" onclick="go('replies')">Посмотреть ответы и написать людям</button></section>`}
function replies(){let list=S.players.filter(p=>p.reply!=='Не иду');return `<section class="card"><h2>Ответы игроков</h2><p class="sub">Здесь только решение до вечера: кто идёт, кто думает, кому написать.</p><div class="notice">Следующее действие: ${S.players.some(p=>p.reply==='Пока думаю')?'напомнить тем, кто думает':'состав собран — переходи к отметке прихода в день игры'}</div></section><div class="list">${list.map(p=>`<div class="item"><div class="avatar">${p.name[0]}</div><div class="grow"><b>${p.name}</b><div class="sub">${p.note||'Нет заметки'}</div></div><span class="badge ${p.reply==='Иду'?'green':p.reply==='Пока думаю'?'warn':''}">${p.reply}</span><button class="action" onclick="open('player:'+p.id)">Открыть</button></div>`).join('')}</div><button class="outline" style="width:100%;margin-top:10px" onclick="open('guest')">＋ Добавить гостя вручную</button>`}
function live(){let todo=S.players.filter(p=>yes(p)&&!arrived(p));let here=S.players.filter(arrived);let unpaid=here.filter(p=>!p.paid);return `<section class="card"><h2>На месте</h2><p class="sub">Это рабочий экран входа. Вверху — только люди, по которым есть действие.</p><div class="grid"><div class="stat"><b>${todo.length}</b><span class="tiny">отметить приход</span></div><div class="stat"><b>${unpaid.length}</b><span class="tiny">принять оплату</span></div></div></section>${todo.length?`<div class="list">${todo.map(p=>`<div class="item"><div class="avatar">${p.name[0]}</div><div class="grow"><b>${p.name}</b><div class="sub">${p.reply}</div></div><button class="primary action" onclick="pHere(${p.id})">Пришёл</button></div>`).join('')}</div>`:''}${unpaid.length?`<section class="card"><h3>Оплата после отметки прихода</h3><div class="list">${unpaid.map(p=>`<div class="item"><div class="avatar">${p.name[0]}</div><div class="grow"><b>${p.name}</b><div class="sub">К оплате 700 ₽</div></div><button class="good action" onclick="pPaid(${p.id})">Принять 700 ₽</button></div>`).join('')}</div></section>`:''}${!todo.length&&!unpaid.length?`<section class="card"><h3>По входу всё готово</h3><p class="sub">Пришли ${here.length} игроков, оплаты отмечены. Можно собирать игру.</p><button class="primary" onclick="go('games')">Создать игру</button></section>`:''}`}
function games(){let here=S.players.filter(arrived);return `<section class="card"><h2>Игры вечера</h2><p class="sub">Создаёшь игру только из тех, кто реально пришёл. Сразу понятно, что делать дальше.</p><button class="primary" onclick="open('game')">＋ Создать игру</button></section>${S.games.length?S.games.map((g,i)=>`<section class="card"><div class="row between"><div><h3>Игра ${i+1}</h3><div class="sub">${g.status==='live'?'Идёт сейчас':'Завершена'} · ${g.people.join(', ')}</div></div><span class="badge ${g.status==='live'?'green':''}">${g.status==='live'?'В ПРОЦЕССЕ':'ГОТОВО'}</span></div><button style="width:100%;margin-top:10px" class="${g.status==='live'?'primary':'outline'}" onclick="finishGame(${i})">${g.status==='live'?'Открыть ведение / завершить':'Посмотреть результат'}</button></section>`).join(''):`<section class="card"><h3>${here.length?'Можно создать первую игру':'Сначала отметь пришедших'}</h3><p class="sub">${here.length?`Сейчас на месте ${here.length} игроков.`:'Игроки для игры берутся из экрана «На месте».'}</p></section>`}`}
function modal(){if(!S.modal)return '';if(S.modal==='send')return sheet('Отправить приглашения',`<p class="sub">Тестовая рассылка изменит ответы игроков, чтобы можно было пройти сценарий дальше.</p>`,`Разослать`,()=>{S.players[0].reply='Иду';S.players[1].reply='Пока думаю';S.players[2].reply='Иду';S.players[3].reply='Приду позже';close()});if(S.modal==='guest')return sheet('Добавить гостя',`<label>Имя гостя<input id="guest" placeholder="Например, Катя"></label>`,`Добавить`,()=>{let n=$('#guest').value.trim();if(n)S.players.push({id:Date.now(),name:n,reply:'Иду',arrival:'pending',paid:false,note:'Гость'});close()});if(S.modal==='game'){let h=S.players.filter(arrived);return sheet('Новая игра',`<p class="sub">В прототипе выбираются все присутствующие. В рабочей версии здесь будет удобная ротация и рассадка.</p><div class="list">${h.map(p=>`<div class="item"><div class="avatar">${p.name[0]}</div><b>${p.name}</b></div>`).join('')||'<p class="sub">Нет отмеченных игроков</p>'}</div>`,`Начать ведение`,()=>{if(h.length)S.games.push({people:h.map(p=>p.name),status:'live'});close()})}let p=S.players.find(x=>S.modal==='player:'+x.id);return sheet(p.name,`<label>Статус участия<select id="reply"><option ${p.reply==='Иду'?'selected':''}>Иду</option><option ${p.reply==='Приду позже'?'selected':''}>Приду позже</option><option ${p.reply==='Пока думаю'?'selected':''}>Пока думаю</option><option ${p.reply==='Не иду'?'selected':''}>Не иду</option></select></label><label>Заметка<textarea id="note">${p.note}</textarea></label>`,`Сохранить`,()=>{p.reply=$('#reply').value;p.note=$('#note').value;close()})}
function sheet(title,content,label,fn){window._ok=fn;return `<div class="modal"><div class="sheet"><div class="row between"><h2>${title}</h2><button class="outline action" onclick="close()">Закрыть</button></div><div class="space"></div>${content}<button class="primary" style="width:100%" onclick="_ok()">${label}</button></div></div>`}function pHere(id){S.players.find(p=>p.id===id).arrival='here';render()}function pPaid(id){S.players.find(p=>p.id===id).paid=true;render()}function finishGame(i){S.games[i].status='done';render()}function render(){$('#app').innerHTML=header()+({announce,replies,live,games}[S.screen]())+modal()}render();
